-- =============================================================================
-- Phase 2.2 — Referential Integrity & Field Encryption
--
-- Written by hand, not generated by `prisma migrate dev`: this project's
-- migration history does not replay cleanly from an empty database (56 of
-- 122 live tables, including `users`, were never created by any migration —
-- see Phase 2.2's own findings register, a new finding this migration does
-- NOT attempt to fix), so the shadow-database diff `migrate dev` needs could
-- not be built. This SQL was instead generated with
-- `prisma migrate diff --from-url <local dev db> --to-schema-datamodel
-- prisma/schema.prisma --script` against a real, fully-migrated local
-- database, then hand-reviewed and adjusted for idempotency before being
-- checked in.
--
-- ADDITIVE/SAFE ONLY. This migration:
--   * DROPS nothing, RENAMES nothing, DELETES no data
--   * Every new column is NULLABLE
--   * Every statement is idempotent (IF NOT EXISTS / DO-block guards)
--   * Changes two `onDelete` behaviors from CASCADE to RESTRICT (see below)
--     — confirmed by a repo-wide search to have zero current regression
--     surface, since no code path deletes a User, Organization or
--     Subscription today.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. vault_records — folder-classification columns (DB-GAP-14).
--
-- These columns are declared in schema.prisma and actively read/written by
-- 7 application files (vault-classification.service.ts, vault-folder.service.ts,
-- vault.controller.ts, home-pulse.service.ts, and others) but were never
-- added by any migration in this project's history. This environment's own
-- local dev database was missing them before this migration ran. Using
-- IF NOT EXISTS because another environment may already have them via a
-- `prisma db push` that (like several other tables documented in Phase 2.2's
-- findings register) was never captured as a migration — this must be a
-- no-op there, and a real reconciliation everywhere else.
-- -----------------------------------------------------------------------------
ALTER TABLE "vault_records" ADD COLUMN IF NOT EXISTS "folder" TEXT;
ALTER TABLE "vault_records" ADD COLUMN IF NOT EXISTS "folderSource" TEXT;
ALTER TABLE "vault_records" ADD COLUMN IF NOT EXISTS "folderReason" TEXT;
ALTER TABLE "vault_records" ADD COLUMN IF NOT EXISTS "folderSuggestion" TEXT;
ALTER TABLE "vault_records" ADD COLUMN IF NOT EXISTS "folderConfidence" INTEGER;
ALTER TABLE "vault_records" ADD COLUMN IF NOT EXISTS "folderStatus" TEXT;
ALTER TABLE "vault_records" ADD COLUMN IF NOT EXISTS "folderUpdatedAt" TIMESTAMP(3);
CREATE INDEX IF NOT EXISTS "vault_records_folder_idx" ON "vault_records"("folder");

-- -----------------------------------------------------------------------------
-- 2. OrganizationWebhook / OrganizationIntegration — field encryption (DB-GAP-06).
--
-- Expand phase only. The pre-existing plaintext columns (`secret`,
-- `configJson`) are left in place as the read fallback for rows written
-- before this change — see src/lib/field-encryption.ts and the updated
-- webhook.service.ts / integration.service.ts. A later, separately-reviewed
-- migration should backfill existing rows into the new encrypted columns
-- and only then drop the plaintext ones (the "contract" phase) — not done
-- here.
-- -----------------------------------------------------------------------------
ALTER TABLE "organization_webhooks" ADD COLUMN IF NOT EXISTS "secretCipher" BYTEA;
ALTER TABLE "organization_webhooks" ADD COLUMN IF NOT EXISTS "secretKeyVersion" TEXT;
ALTER TABLE "organization_webhooks" ALTER COLUMN "secret" DROP NOT NULL;

ALTER TABLE "organization_integrations" ADD COLUMN IF NOT EXISTS "configJsonCipher" BYTEA;
ALTER TABLE "organization_integrations" ADD COLUMN IF NOT EXISTS "configKeyVersion" TEXT;

-- -----------------------------------------------------------------------------
-- 3. Dangerous cascade chains reaching financial/audit records (DB-GAP-10, DB-GAP-11).
--
-- Both were CASCADE: deleting a User could silently destroy that user's
-- entire billing ledger (User -> Subscription -> BillingHistory) or an
-- organization's audit trail (User -> Organization -> OrganizationAuditLog).
-- Changed to RESTRICT so that delete fails loudly instead, until an explicit
-- archival/anonymization step exists. Verified by a repo-wide search: no
-- code path deletes a Subscription, Organization or User today, so this has
-- zero current regression surface.
-- -----------------------------------------------------------------------------
DO $$ BEGIN
  ALTER TABLE "billing_history" DROP CONSTRAINT IF EXISTS "billing_history_subscriptionId_fkey";
  ALTER TABLE "billing_history" ADD CONSTRAINT "billing_history_subscriptionId_fkey"
    FOREIGN KEY ("subscriptionId") REFERENCES "subscriptions"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE "organization_audit_logs" DROP CONSTRAINT IF EXISTS "organization_audit_logs_organizationId_fkey";
  ALTER TABLE "organization_audit_logs" ADD CONSTRAINT "organization_audit_logs_organizationId_fkey"
    FOREIGN KEY ("organizationId") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- -----------------------------------------------------------------------------
-- 4. dedupeKey uniqueness (DB-GAP-12, DB-GAP-13).
--
-- Both fields are named "dedupeKey" but were previously only indexed, not
-- unique — the one field in this schema that already enforces this correctly
-- (ForensicProvenanceEvent.dedupeKey) shows the intended pattern. Scoped
-- per-owner, matching actual usage. Verified against this local database:
-- zero existing duplicate (owner, dedupeKey) pairs in either table before
-- this constraint was added (checked via a direct query, not assumed) — not
-- independently verified against production data.
-- -----------------------------------------------------------------------------
CREATE UNIQUE INDEX IF NOT EXISTS "notifications_userId_dedupeKey_key" ON "notifications"("userId", "dedupeKey");
CREATE UNIQUE INDEX IF NOT EXISTS "platform_events_ownerUserId_dedupeKey_key" ON "platform_events"("ownerUserId", "dedupeKey");
